function resolveBattedBallPhysicalTruth(input = {}) {
  const identity = String(input.identity || "ordinary-contact");
  const quality = resolveContactQuality({ ...input, identity });
  const ballType = resolveBattedBallType({ ...input, identity, contactQuality: quality.contactQuality });
  const pace = resolveBattedBallPace({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  const direction = resolveBattedBallDirection({ ...input, identity });
  const depth = resolveBattedBallDepth({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  return deepFreeze({
    version: VERSION,
    identity,
    contactQuality: quality.contactQuality,
    ballType,
    pace: pace.pace,
    direction: direction.direction,
    depth: depth.depth,
    executionEvidence: {
      actualPitch: clone(input.actualPitch || {}),
      recognition: clone(input.recognition || {}),
      swing: { action: input.action || "swing", contact: input.contact === true, swingIntent: input.swingIntent || "normal" },
      continuousContactScore: quality.score,
      paceScore: pace.score,
      depthScore: depth.score,
      rolls: { contactQuality: quality.roll, ballType: resolveRoll(input, "ballType", RNG_NAMESPACES.ballType, identity), pace: pace.roll, direction: direction.roll, depth: depth.roll },
      depthRollConsumed: depth.consumed
    }
  });
}

function buildGroundBallDefensiveOpportunity(input = {}) {
  const physicalTruth = input.physicalTruth || {};
  const forceChain = input.forceChain || (ForceAdvancement ? ForceAdvancement.buildInitialLiveBallForceChain({
    runners: input.runners,
    batterRunnerId: input.batterRunner?.runnerId || "batter-runner"
  }) : null);
  const forceState = forceChain && ForceAdvancement
    ? ForceAdvancement.deriveCompatibilityForceState(forceChain, { outs: input.outs })
    : input.forceState || deriveForceState({ runners: input.runners, outs: input.outs });
  const defensiveAccess = resolveGroundBallDefensiveAccess(input);
  const ballContext = projectGroundBallCompatibilityContext(physicalTruth, defensiveAccess);
  const runnerRealization = buildGroundBallRunnerRealization({ ...input, forceChain, forceState, defensiveAccess, ballContext });
  if (!runnerRealization) return null;
  const timingWindows = buildGroundBallTimingWindows({ ballContext, runnerRealization });
  const homeRunner = runnerRealization.existingRunners.find(state => state.originBase === 3
    && state.targetBase === "home" && ["advancing", "committed"].includes(state.movementState));
  const choices = defensiveAccess.supported ? ["secureFirstBaseOut"] : [];
  const thirdBase = defensiveAccess.playerPosition === "三壘手";
  if (defensiveAccess.supported && forceState.forceAtSecond) {
    if (defensiveAccess.playerPosition === "游擊手") choices.push("forceSecond");
    if (Number(input.outs) < 2) choices.push(thirdBase ? "initiate543"
      : defensiveAccess.playerPosition === "游擊手" ? "startDoublePlaySecond" : "initiate463");
  }
  if (defensiveAccess.supported && thirdBase && forceState.forceAtThird) choices.push("stepThird");
  if (!thirdBase && defensiveAccess.supported && forceState.forceAtHome && timingWindows.homeOutWindow.state !== "expired") choices.push("homeForceOut");
  else if (!thirdBase && defensiveAccess.supported && homeRunner && timingWindows.homeOutWindow.state !== "expired") choices.push("preventRunHome");
  return deepFreeze({
    version: VERSION,
    identity: String(input.identity || "ordinary-ground-ball"),
    sourceAuthority: "BattedBallPhysicalTruth",
    physicalTruth: clone(physicalTruth),
    ...(Opportunity && [Opportunity.GROUND_TOPOLOGY_VERSION, Opportunity.FIRST_BASE_GROUND_TOPOLOGY_VERSION].includes(input.defenderContext?.defensiveOpportunity?.topologyVersion)
      ? { defensiveOpportunity: clone(input.defenderContext.defensiveOpportunity) } : {}),
    forceChain,
    forceState,
    runnerRealization,
    runnerPhysicalStates: runnerRealization.runnerPhysicalStates,
    defensiveAccess,
    ballContext,
    timingWindows,
    availableDecisionIds: choices,
    firstLegState: { status: "pending", targetBase: forceState.forceAtSecond ? "second" : "first" },
    continuationState: { status: "pendingReassessment", window: timingWindows.relayToFirstWindow.state, targetBase: "first" },
    supported: defensiveAccess.supported,
    settlementApplied: false
  });
}

function ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options = {}) {
  if (!match || typeof BattedBallGroundDefense === "undefined" || typeof OffensivePlateApproach === "undefined") return null;
  if (match.offensiveTacticalActionState?.selectedTacticalAction !== "standardAttack") return null;
  const playerPosition = match.developmentPositionOverride || getHighSchoolInfieldAssignmentPosition(match, player);
  const batter = getHighSchoolMatchSimulationEntity(match, match.currentBatter);
  const paIdentity = `${createHighSchoolOffensiveTacticalIdentity(match)}|ordinary-contact`;
  const existing = BattedBallGroundDefense.normalizeHandoff(match.groundBallInPlayState);
  const existingLineDrive = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  const existingFlyBall = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (existing?.identity === `${paIdentity}|ground-defense`) {
    if (existing.supported && !existing.settlementApplied) assertHighSchoolGroundParticipant(match);
    match.groundBallInPlayState = existing;
    return existing;
  }
  if (existingLineDrive?.identity === `${paIdentity}|line-drive-catch`) {
    if (existingLineDrive.supported && !existingLineDrive.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingLineDrive.physicalTruth, "2B", "player");
    match.lineDriveCatchState = existingLineDrive;
    return null;
  }
  if (existingFlyBall?.identity === `${paIdentity}|fly-ball-catch`) {
    if (existingFlyBall.supported && !existingFlyBall.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingFlyBall.physicalTruth, existingFlyBall.defenderContext?.position, existingFlyBall.defenderContext?.defenderId);
    match.flyBallCatchState = existingFlyBall;
    return null;
  }
  const defender = {
    ...getDefensiveSimulationCapability(player, "內野手"),
    ...(options.situationOverrides?.playerCapabilities || {})
  };
  const physicalDefenderContext = physicalTruth => getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, {
    playerPosition, catching: defender.fielding, reaction: defender.reaction, range: defender.range
  }, options);
  const offense = getHighSchoolProvisionalOffensiveTacticalCapabilities(match);
  const initial = OffensivePlateApproach.createPlateAppearanceState({
    paIdentity,
    batterId: match.currentBatter,
    approach: "balancedAttack",
    context: { outs: match.outs, runners: match.runners.slice(), hasRunner: match.runners.some(Boolean) }
  });
  const fixture = options.ordinaryPlateAppearance || {};
  const pitch = fixture.pitch || { pitchLocationClass: "hitterPitch" };
  const pitchOptions = {
    recognitionRoll: fixture.recognitionRoll ?? 0,
    decisionRoll: fixture.decisionRoll ?? 0,
    contactRoll: fixture.contactRoll ?? 0,
    foulRoll: fixture.foulRoll ?? 1,
    physicalRolls: fixture.physicalRolls,
    outcomeRoll: fixture.outcomeRoll,
    physicalOutcomeResolver({ physicalTruth }) {
      const access = BattedBallGroundDefense.resolveGroundBallDefensiveAccess({
        physicalTruth,
        defenderContext: physicalDefenderContext(physicalTruth)
      });
      if (access.supported) return {
        result: "groundBallDefensePending",
        authority: "bbpB1PhysicalDefensePending",
        contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
        resolvedContact: null
      };
      if (typeof BattedBallLineDriveDefense !== "undefined") {
        const airborneContext = BattedBallLineDriveDefense.buildAirborneBallContext(physicalTruth);
        const catchAccess = airborneContext ? BattedBallLineDriveDefense.resolveCatchAccess({
          airborneContext,
          defenderContext: physicalDefenderContext(physicalTruth)
        }) : null;
        const catchWindow = catchAccess ? BattedBallLineDriveDefense.buildCatchTimingWindow({ airborneContext, defensiveAccess: catchAccess }) : null;
        if (catchAccess?.supported && catchWindow?.state !== "expired") return {
          result: "lineDriveCatchPending",
          authority: "bbpB2APhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      if (typeof BattedBallFlyBallDefense !== "undefined") {
        const flyBallDefender = getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options);
        const flyBallOpportunity = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
          identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: [], outs: match.outs,
          runnerEntities: [], defenderContext: flyBallDefender
        });
        if (flyBallOpportunity?.supported) return {
          result: "flyBallCatchPending",
          authority: "bbpB2B1PhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      return null;
    }
  };
  const plateAppearanceState = OffensivePlateApproach.simulatePlateAppearance({
    state: initial,
    abilities: {
      observe: Number(offense.baseballIQ) || 5,
      baseballIQ: Number(offense.baseballIQ) || 5,
      ballSense: Number(offense.ballSense) || 5,
      batting: Number(offense.batting) || 5,
      power: Number(batter?.power) || Number(offense.batting) || 5,
      bats: batter?.bats || "R"
    },
    pitchSequence: [pitch],
    pitchOptions: [pitchOptions]
  });
  match.ordinaryDefensivePlateAppearanceState = JSON.parse(JSON.stringify(plateAppearanceState));
  const physicalTruth = plateAppearanceState.battedBallPhysicalTruth;
  const runnerEntities = match.runners.map((runnerId, index) => {
    if (!runnerId) return null;
    const entity = getHighSchoolMatchSimulationEntity(match, runnerId);
    return {
      runnerId,
      originBase: index + 1,
      speed: Number(entity?.speed) || 5,
      reaction: Number(entity?.reaction) || Number(entity?.defense) || 5,
      baseballIQ: Number(entity?.baseballIQ) || Number(entity?.decision) || 5
    };
  }).filter(Boolean);
  if (plateAppearanceState.result === "lineDriveCatchPending" && physicalTruth && typeof BattedBallLineDriveDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.flyBallCatchState = null;
    match.lineDriveCatchState = BattedBallLineDriveDefense.buildCatchOpportunity({
      identity: `${paIdentity}|line-drive-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: physicalDefenderContext(physicalTruth)
    });
    return null;
  }
  if (plateAppearanceState.result === "flyBallCatchPending" && physicalTruth && typeof BattedBallFlyBallDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.lineDriveCatchState = null;
    match.flyBallCatchState = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
      identity: `${paIdentity}|fly-ball-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
    });
    return null;
  }
  if (plateAppearanceState.result !== "groundBallDefensePending" || !physicalTruth) {
    const ordinaryInfield = isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
      version: BattedBallGroundDefense.VERSION,
      identity: `${paIdentity}|ground-defense`,
      sourceAuthority: "unsupportedOrdinaryContactLegacyFallback",
      physicalTruth: physicalTruth ? JSON.parse(JSON.stringify(physicalTruth)) : null,
      supported: false,
      ...(ordinaryInfield ? { fallbackAuthority: "existingOrdinaryPhysicalOutcome",
        defensiveOpportunity: physicalTruth ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null }
        : { fallbackAuthority: "existingSyntheticDefensiveContext" }),
      legacyFallbackResult: plateAppearanceState.result || ""
    });
    match.lineDriveCatchState = physicalTruth?.ballType === "lineDrive" && typeof BattedBallLineDriveDefense !== "undefined"
      ? BattedBallLineDriveDefense.buildCatchOpportunity({
        identity: `${paIdentity}|line-drive-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: physicalDefenderContext(physicalTruth)
      }) : null;
    match.flyBallCatchState = physicalTruth?.ballType === "flyBall" && typeof BattedBallFlyBallDefense !== "undefined"
      ? BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
        identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
      }) : null;
    return match.groundBallInPlayState;
  }
  const forceState = BattedBallGroundDefense.deriveForceState({ runners: match.runners, outs: match.outs });
  match.lineDriveCatchState = null;
  match.flyBallCatchState = null;
  match.groundBallInPlayState = BattedBallGroundDefense.buildGroundBallDefensiveOpportunity({
    identity: `${paIdentity}|ground-defense`,
    physicalTruth,
    runners: match.runners,
    outs: match.outs,
    forceState,
    runnerEntities,
    batterRunner: { runnerId: match.currentBatter, speed: Number(batter?.speed) || 5 },
    preContactRunnerStates: options.preContactRunnerStates || {},
    defenderContext: physicalDefenderContext(physicalTruth)
  });
  const firstBaseContext = createHighSchoolFirstBaseContext(match, match.groundBallInPlayState, options);
  if (firstBaseContext) match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
    ...match.groundBallInPlayState, defensiveOpportunity: getHighSchoolDefensiveOpportunity(match, physicalTruth), firstBaseContext });
  return match.groundBallInPlayState;
}

function getHighSchoolDefensiveOpportunity(match, physicalTruth) {
  if (typeof DefensiveOpportunityFoundation === "undefined") return null;
  const prior = match?.groundBallInPlayState;
  const samePhysical = prior?.physicalTruth?.identity === physicalTruth?.identity;
  const historical = samePhysical && (prior?.defensiveOpportunity || (prior?.defensiveAccess?.reachResolution
    ? { topologyVersion: "regulation-coarse-zones-v1" } : null));
  const responsibility = DefensiveOpportunityFoundation.deriveGroundResponsibility?.(physicalTruth,
    DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION);
  // The classifier is shared by player and NPC assignments. Unchanged SS/2B
  // lanes keep their existing execution identities; saved lanes retain their version.
  const topologyVersion = historical ? historical.topologyVersion
    : responsibility?.primaryPosition === "1B" ? DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION
      : responsibility?.primaryPosition === "3B" ? DefensiveOpportunityFoundation.GROUND_TOPOLOGY_VERSION : undefined;
  return DefensiveOpportunityFoundation.resolveDefensiveOpportunity({
    physicalTruth, activeRoster: match?.rosters?.[match.defenseTeam], topologyVersion
  });
}

function beginAutomaticGroundBallSituationExecution(match) {
  if (!match || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
    || situation.lifecycleState !== "admitted" || situation.admission?.admittedToPlayer) return situation;
  assertHighSchoolGroundParticipant(match);
  const route = situation.legalRoutes[0];
  situation = MatchSituationLifecycle.beginExecution(situation, {
    selectedRoute: route?.routeId || route?.matchDecision || "automatic",
    handoffRef: match.groundBallInPlayState?.identity || "",
    reason: "automaticGroundBallExecution"
  });
  match.activeSituation = situation;
  return situation;
}

function buildHighSchoolShortstopExecution(match, situation, choice, sample) {
  const handoff = match.groundBallInPlayState;
  if (!Number.isFinite(sample) || sample < 0 || sample >= 1) throw new Error("Invalid SS execution sample");
  assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "SS", "player");
  if (situation.playerPosition !== "游擊手" || !handoff.supported) throw new Error("Invalid SS production context");
  const secureResolution = resolveHighSchoolCanonicalSecure(match, handoff, sample);
  const input = getHighSchoolControlledDecisionInput(match, { ...handoff, secureResolution });
  const opportunity = DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input);
  const controlled = opportunity.status === "controlledDecision";
  const selection = controlled ? DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, choice.routeId, input) : null;
  const thrown = selection ? DefensiveDecisionThrowFoundation.resolveThrow({ input, opportunity, selection,
    capabilities: { defenderId: "player", arm: situation.playerCapabilities.arm, throwing: situation.playerCapabilities.throwing },
    transferState: secureResolution.secureQuality === "bobbleButControlled" ? "delayed" : "ready" }) : null;
  const swing = (sample - 0.5) * 4;
  const receiver = selection?.route.receiverPosition
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], selection.route.receiverPosition) : null;
  const receiverCapabilities = receiver ? getDefensiveSimulationCapability(receiver, receiver.position, match) : {};
  const receiverReady = Boolean(receiver && (Number(receiverCapabilities.fielding) || 5) + swing >= 3.2);
  input.receiverState = { receiverId: receiver?.id || null, ready: receiverReady, atBase: true, tagAvailable: receiverReady, tagDelay: 1 };
  const decisionThrowState = { opportunity, preControlIntent: choice.routeId, selection, activeSelection: selection, throwResolution: thrown };
  // Failed acquisition has no controlled decision or throw. Preserve the existing
  // Foundation's no-contest diagnostic so lifecycle recovery still has an owner.
  let runnerThrowTiming = selection ? null : DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({
    stage: decisionThrowState, runnerState: null, windowState: "expired", receiverFact: "unavailable" });
  let firstLegSettlement = null;
  if (selection) {
    const timingArgs = { input, opportunity, selection, throwResolution: thrown,
      runnerState: input.runnerPhysicalStates.find(r => r.runnerId === selection.route.targetRunnerId),
      receiverState: input.receiverState, resolveThirdOut: resolveHighSchoolThirdOutIntegrity };
    runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.resolveTiming(timingArgs);
    firstLegSettlement = DefensiveRunnerThrowSettlementFoundation.deriveSettlement({ ...timingArgs, timing: runnerThrowTiming });
  }
  const firstOut = firstLegSettlement?.outRecorded === true;
  const continuationWindow = handoff.timingWindows.relayToFirstWindow.state;
  const isDoublePlay = choice.infieldRoute === "doublePlay";
  // Relay completion reuses the established 2B/SS receive-turn-deliver model.
  const relay = resolveInfieldRelayToFirst(situation, firstOut, sample, continuationWindow, receiverCapabilities);
  const secondOut = isDoublePlay && firstOut && situation.outs < 2 && relay.secondOutAvailable;
  const retirements = firstOut ? [{ runnerId: selection.route.targetRunnerId, targetBase: selection.route.targetBase,
    outType: firstLegSettlement.playType === "batterRunner" ? "batterRunnerBeforeFirst" : firstLegSettlement.playType === "force" ? "force" : "nonForceTag", sequence: 1 }] : [];
  if (secondOut) retirements.push({ runnerId: situation.batterId, targetBase: "first", outType: "batterRunnerBeforeFirst", sequence: 2 });
  // Complete all committed actors after the first-leg contest. The existing force
  // owner accounts for in-transit runners, collisions, and force removal after outs.
  const runnerSettlement = ForceAdvancement.settleForceAdvancement({ forceChain: situation.forceChain,
    movementIntents: situation.movementIntents, retirements });
  const error = (secureResolution.attemptAvailable && !secureResolution.secured) || thrown?.throwQuality === "offline";
  const resultCode = secondOut ? "twoOuts" : firstOut ? "oneOut" : error ? "error" : "zeroOuts";
  const detailedResult = secondOut ? "completedDoublePlay" : firstOut ? (isDoublePlay ? "secondStageExpired" : "cleanOut")
    : error ? (secureResolution.secured ? "inaccurateThrow" : "fieldingError") : !secureResolution.secured ? "lateFielding"
      : choice.infieldRoute === "controlledNoThrow" ? "controlledNoThrow" : "lateThrow";
  const primaryCause = !secureResolution.secured ? "playerFieldingControl" : thrown?.throwQuality === "offline" ? "playerFirstThrow"
    : !receiverReady && selection?.route.action !== "holdBall"
      ? selection?.route.receiverPosition === "1B" ? "teammateFirstBaseReceive" : selection?.route.receiverPosition === "C" ? "teammateHomeReceive" : "teammatePivot"
      : isDoublePlay && firstOut && !relay.turn && situation.batterSpeed < 8 && continuationWindow !== "narrow" ? "teammatePivot"
        : isDoublePlay && firstOut && relay.turn && !relay.firstBaseReceive ? "teammateFirstBaseReceive"
          : choice.infieldRoute === "controlledNoThrow" ? "balancedExecution"
            : !firstOut || (isDoublePlay && !secondOut) ? "timingWindow" : "balancedExecution";
  const resolution = attachDefensiveOutcomeExplanation(situation, choice, {
    familyId: "infield", route: choice.infieldRoute, routeId: choice.routeId, initialRoute: choice.routeId, activeRoute: choice.routeId,
    playerRole: "initiator", responsibility: situation.responsibility, resultCode, detailedResult,
    tier: secondOut ? "strong" : firstOut || choice.infieldRoute === "controlledNoThrow" ? "mixed" : "failure",
    decisionQuality: choice.advisable === "strong" ? "strong" : choice.advisable === "aggressive" ? "aggressive" : choice.advisable === "conservative" ? "conservative" : "reasonable",
    executionQuality: firstOut ? (isDoublePlay && !secondOut ? "partial" : "complete") : error ? "misplay" : choice.infieldRoute === "controlledNoThrow" ? "controlled" : "late",
    runnerSettlement, runnerSettlementIdentity: situation.runnerSettlementIdentity, outsCreated: runnerSettlement.outsCreated,
    runnerChanges: runnerSettlement.runnerChanges, runnersAfter: runnerSettlement.runnersAfter,
    scoringRunnerIds: runnerSettlement.scoringRunnerIds, runsAllowed: runnerSettlement.runsAllowed, error,
    primaryCause, secondaryCause: "", responsibleActor: primaryCause.startsWith("teammate") ? "teammate" : primaryCause === "timingWindow" ? "timingWindow" : "player",
    playerResponsibility: error ? "major" : "handled", teammateResponsibility: primaryCause.startsWith("teammate") ? "major" : isDoublePlay ? "shared" : "none",
    causeExplanation: primaryCause === "teammatePivot" ? "傳球的接球端未完成接球或轉傳；二壘手與游擊手的責任分開記錄。"
      : primaryCause === "teammateFirstBaseReceive" ? "傳球已進入一壘接球位置，但一壘手未完成接球；傳球與接球責任分開記錄。" : getSecondBaseCauseExplanation(primaryCause, ""),
    playerLeg: { reach: handoff.defensiveAccess.reachResolution.reached ? "completed" : "late",
      control: secureResolution.secured ? "completed" : "failed", transfer: thrown?.releaseQuality === "delayedRelease" ? "delayed" : controlled ? "completed" : "notReached",
      firstThrow: thrown?.throwAttempted ? thrown.throwQuality === "offline" ? "failed" : "completed" : "notAttempted" },
    teammateLeg: { receiver: receiverReady ? "completed" : "notReached", ...(isDoublePlay ? {
      secondBaseReceive: relay.receive ? "completed" : "notCompleted", secondBasePivot: relay.turn ? "completed" : "notCompleted",
      secondBaseSecondThrow: relay.turn ? "completed" : "notCompleted", firstBaseReceive: relay.firstBaseReceive ? "completed" : "notCompleted" } : {}) },
    firstLegState: { status: firstOut ? "completed" : "failed", targetBase: selection?.route.targetBase || null },
    continuationState: { status: secondOut ? "completed" : firstOut && isDoublePlay ? "windowClosed" : "settledByActorOutcomes", targetBase: isDoublePlay ? "first" : null, window: continuationWindow },
    timingResolution: { firstLeg: runnerThrowTiming, firstLegSettlement, relayToFirstWindow: continuationWindow },
    ballContext: situation.ballContext.type, ballDirection: situation.ballDirection, ballDepth: situation.ballDepth,
    batterSpeed: situation.batterSpeed, runnerSpeed: Math.max(...situation.runnerSpeeds.filter(Number.isFinite), 0),
    ...situation.playerCapabilities, firstStage: secureResolution.margin ?? handoff.defensiveAccess.reachResolution.margin,
    secondStage: thrown?.accuracyMargin ?? 0, returnTiming: 0, windows: situation.windows
  });
  return { sample, choice: { routeId: choice.routeId, matchDecision: choice.matchDecision }, secureResolution,
    decisionThrowState,
    runnerThrowTiming, resolution: attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) };
}

function resolveHighSchoolDefensivePlay(match, decision, randomSource = Math.random) {
  const pending = match?.activeSituation;
  if ((match?.groundBallInPlayState?.runnerThrowTiming || match?.groundBallInPlayState?.shortstopExecution) && pending?.lifecycleState === "resolved" && pending.resolution?.executionEvidence) {
    validateHighSchoolDecisionThrowState(match);
    const selected = pending.legalRoutes.find(route => route.matchDecision === decision || route.routeId === decision);
    if (!selected || (selected.routeId || selected.matchDecision) !== pending.decision?.selectedRoute) throw new Error("Stale defensive decision after execution");
    return pending.resolution.executionEvidence;
  }
  if (match?.positionDecisionFamily === "infield" && match.defensiveSituation?.familyId === "infield") {
    if (match.defensiveSituation.groundBallDefensiveContext?.supported) {
      assertHighSchoolGroundParticipant(match);
    }
    return infieldDecisionFamily.resolve(match.defensiveSituation, decision, match, randomSource);
  }
  if (match?.position === "捕手") return resolveHighSchoolCatcherDecision(match, decision, randomSource);
  return resolveLegacyHighSchoolDefensivePlay(match, decision, randomSource);
}

function resolveRoutineDefensivePlay(match, situation = match?.defensiveSituation, randomSource = null, options = {}) {
  if (!match || situation?.familyId !== "infield") return null;
  if (situation.groundBallDefensiveContext?.supported) {
    assertHighSchoolGroundParticipant(match);
  }
  const legalChoices = infieldDecisionFamily.generateLegalChoices(situation, match);
  const classification = classifyPositionFamilyPlay(situation, legalChoices, true);
  if (classification.eventClassification !== "playerRoutinePlay" && options.densitySuppressed !== true) return null;
  const source = randomSource === null ? () => nextHighSchoolMatchSimulationRandom(match) : randomSource;
  const routineChoice = situation.groundBallDefensiveContext?.firstBaseContext && legalChoices[0]?.routeId === "pitcherCoverFirst"
    ? legalChoices[0] : legalChoices.find(choice => choice.routeId === "coverSecondFor643") || legalChoices.find(choice => choice.matchDecision === "secure") || legalChoices[0];
  const resolution = routineChoice ? infieldDecisionFamily.resolve(situation, routineChoice.matchDecision, match, source) : null;
  if (!resolution) return null;
  return Object.freeze({
    ...resolution,
    // Density suppression already admitted this execution as a routine play.
    // Reusing the candidate's meaningful label would make routine settlement reject it.
    eventClassification: "playerRoutinePlay",
    decisionTension: classification.decisionTension,
    executionRoute: resolution.firstBaseEvidence ? routineChoice.route : getInfieldRoutineExecutionRoute(situation)
  });
}

function prepareHighSchoolDefensiveMomentFromSimulation(match, options = {}) {
  if (match.activeSituation
    && !MatchSituationLifecycle.canResumeSimulation(match.activeSituation)) return null;
  const opportunity = findHighSchoolMatchOpportunity(match, options.opportunityTraceId);
  const densityState = ensureHighSchoolMatchDecisionDensityState(match);
  const flowState = {
    momentIndex: match.momentIndex,
    currentMomentId: match.currentMomentId,
    simulationPhase: match.simulationPhase,
    currentDomain: match.currentDomain,
    currentAssignment: match.currentAssignment
  };
  const primaryDefensiveDecision = flowState.simulationPhase === "moment_1_resolved"
    && (densityState?.defensiveMeaningfulDecisionCount || 0) === 0;
  match.pendingDefensiveResumeState = {
    simulationPhase: primaryDefensiveDecision ? "moment_2_resolved" : flowState.simulationPhase,
    momentIndex: primaryDefensiveDecision ? 1 : flowState.momentIndex,
    currentMomentId: primaryDefensiveDecision ? highSchoolYearOneMomentIds[1] : flowState.currentMomentId,
    currentDomain: "flow",
    currentAssignment: flowState.currentAssignment
  };
  match.currentBatter = getHighSchoolMatchLineupBatter(match, match.offenseTeam)?.id || "";
  match.momentIndex = 1;
  match.currentMomentId = primaryDefensiveDecision ? highSchoolYearOneMomentIds[1]
    : `hs_y1_match_defense_${(densityState?.defensiveMeaningfulDecisionCount || 0) + 1}`;
  match.currentDomain = "defense";
  const offensiveTacticalState = prepareHighSchoolOffensiveTacticalAction(match, options);
  if (offensiveTacticalState) {
    advanceHighSchoolOffensiveTacticalReveal(match, options.tacticalRevealPhase || "lateReveal");
  } else {
    match.opponentTacticalTruth = {
      code: match.previousMomentDecision === "zone" ? "hitAndRun" : match.previousMomentDecision === "attack" ? "earlyBreak" : "shortSwing",
      targetRunnerId: match.runners[1] || match.runners[0] || match.runners[2] || ""
    };
  }
  const productionBunt = offensiveTacticalState && typeof OffensiveBuntExecution !== "undefined"
    ? resolveHighSchoolProductionBuntPitch(match, {
      ...(options.buntPitchOptions || {}),
      initialCount: options.buntInitialCount
    }) : null;
  if (productionBunt?.event) {
    match.momentIndex = flowState.momentIndex;
    match.currentMomentId = flowState.currentMomentId;
    match.simulationPhase = flowState.simulationPhase;
    match.currentDomain = flowState.currentDomain;
    match.currentAssignment = flowState.currentAssignment;
    match.pendingDefensiveResumeState = null;
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, productionBunt.event, productionBunt.status);
    return productionBunt.event;
  }
  const buntHandoff = productionBunt?.shouldBuildDefense ? ensureHighSchoolBuntBallInPlayHandoff(match) : null;
  const groundBallHandoff = !productionBunt && offensiveTacticalState?.selectedTacticalAction === "standardAttack"
    ? ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options) : null;
  // Only this plate appearance's handoff may own a ground-ball lifecycle or apply guard.
  // A prior completed grounder must not suppress a later routine defensive settlement.
  match.groundBallInPlayState = groundBallHandoff;
  if (buntHandoff && !buntHandoff.supported) {
    if (buntHandoff.fallbackPresented !== true) {
      const fallbackText = buntHandoff.ballContext.downstreamSupport === "unsupportedPopBuntFallback"
        ? "短打形成小飛球，壘上跑者回頭確認球是否落地；本階段不預判接殺或離壘出局。"
        : `短打落在${buntHandoff.ballContext.physicalTruth.placement === "thirdBaseSide" ? "三壘側" : buntHandoff.ballContext.physicalTruth.placement === "firstBaseSide" ? "一壘側" : "投手附近"}；此守備位置尚未納入二壘手垂直切片。`;
      match.buntBallInPlayState = Object.freeze({ ...JSON.parse(JSON.stringify(buntHandoff)), fallbackPresented: true });
      const fallbackEvent = recordHighSchoolMatchSimulationEvent(match, {
        type: "buntDefensiveFallback", presentationImportance: "attention", inning: match.inning, half: match.half,
        assignment: fallbackText, presentation: fallbackText, outs: match.outs, scores: match.scores, runners: match.runners
      });
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, fallbackEvent, "unsupported-bunt-defense");
      return fallbackEvent;
    }
    return null;
  }
  const lineDriveCatchOpportunity = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  if (!productionBunt && lineDriveCatchOpportunity?.supported) {
    resolveHighSchoolLineDriveCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolLineDriveCatchResolution(match);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-line-drive-catch");
    return catchEvent;
  }
  const flyBallCatchOpportunity = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (!productionBunt && flyBallCatchOpportunity?.supported) {
    resolveHighSchoolFlyBallCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolFlyBallCatchResolution(match);
    const tagUpSituation = createHighSchoolRunnerTagUpSituation(match);
    if (tagUpSituation?.admission?.admittedToPlayer && tagUpSituation.lifecycleState === "presented") {
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "tag-up-decision-created");
      return catchEvent;
    }
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-fly-ball-catch");
    return catchEvent;
  }
  if (groundBallHandoff && !groundBallHandoff.supported
    && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position)) {
    // Preserve this PA's physical source for every assignment. Unsupported contact
    // cannot acquire a synthetic player primary merely by entering the infield family.
    const result = groundBallHandoff.legacyFallbackResult;
    const before = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const facts = applyHighSchoolSimulatedPlateAppearance(match, result, match.currentBatter, match.offenseTeam);
    const after = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const event = recordHighSchoolRoutinePlateAppearance(match, match.currentBatter, result, before, after,
      Math.max(0, after.scores[match.offenseTeam] - before.scores[match.offenseTeam]), {
        ...facts, physicalTruth: groundBallHandoff.physicalTruth, defensiveOpportunity: groundBallHandoff.defensiveOpportunity,
        outcomeAuthority: "existingOrdinaryPhysicalOutcome",
        eventClassification: "ordinaryPlay" });
    advanceHighSchoolMatchBattingOrder(match, match.offenseTeam);
    match.ordinaryDefensivePlateAppearanceState = OffensivePlateApproach.markResultApplied(match.ordinaryDefensivePlateAppearanceState);
    Object.assign(match, { momentIndex: flowState.momentIndex, currentMomentId: flowState.currentMomentId,
      simulationPhase: flowState.simulationPhase, currentDomain: flowState.currentDomain, currentAssignment: flowState.currentAssignment,
      pendingDefensiveResumeState: null, defensiveSituation: {}, positionDecisionFamily: "",
      playerEventClassification: "ordinaryPlay", decisionGate: null, decisionTension: "none" });
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...groundBallHandoff, settlementApplied: true });
    assertHighSchoolMatchStateIntegrity(match, "ordinary-outside-player-physical-scope");
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "outside-player-physical-scope");
    return event;
  }
  if (buntHandoff) match.ballContext = JSON.parse(JSON.stringify(buntHandoff.ballContext));
  else if (groundBallHandoff?.supported) match.ballContext = JSON.parse(JSON.stringify(groundBallHandoff.ballContext));
  else setHighSchoolDefensiveBallContext(match, options.ballContextType || "");
  match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  const priorTier = match.completedMoments[0]?.tier;
  match.coachInstruction = priorTier === "strong"
    ? "前一段執行已建立信任；現在先讀出局數，再決定是否挑戰額外出局。"
    : priorTier === "mixed"
      ? "先把最穩定的守備出局處理乾淨，不讓壘況繼續擴大。"
      : "前一段結果不影響你的守備資格；這一球只看補位與最短合法出局。";
  if (isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position)) {
    match.defensiveSituation = {};
    const buntOverrides = getHighSchoolBuntDefensiveSituationOverrides(buntHandoff);
    const groundBallOverrides = getHighSchoolGroundBallDefensiveSituationOverrides(groundBallHandoff);
    const physicalOverrides = buntOverrides || groundBallOverrides;
    buildInfieldMeaningfulMoment(match, player, physicalOverrides
      ? { ...(options.situationOverrides || {}), ...physicalOverrides }
      : options.situationOverrides || {});
    match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  } else {
    match.positionDecisionFamily = "";
    match.currentFieldingPosition = "";
    match.defensiveSituation = {};
  }
  match.opponentAdjustment = "跑者與打者的準備動作出現變化；只呈現你在場上能看見的線索。";
  const legalChoices = getHighSchoolDefensiveMomentChoices(match);
  const classification = match.defensiveSituation?.familyId === "infield"
    ? classifyHighSchoolMatchDefensiveOpportunity(match, match.defensiveSituation, legalChoices, true)
    : Object.freeze({ eventClassification: "playerMeaningfulDecision", decisionTension: "meaningful", gate: null });
  match.playerEventClassification = classification.eventClassification;
  match.decisionTension = classification.decisionTension;
  match.decisionGate = classification.gate ? JSON.parse(JSON.stringify(classification.gate)) : null;
  applyHighSchoolMatchDefensiveDecisionDensity(match, classification.density, classification.eventClassification === "playerMeaningfulDecision");
  updateHighSchoolMatchDefensiveOpportunityFromSituation(match, opportunity, match.defensiveSituation, legalChoices, classification);
  setHighSchoolCoachTacticalDirection(match);
  createGroundBallMatchSituation(match, legalChoices, classification, opportunity);
  if (classification.eventClassification === "playerRoutinePlay") {
    beginAutomaticGroundBallSituationExecution(match);
    const resolution = resolveRoutineDefensivePlay(match, match.defensiveSituation, options.randomSource ?? null, {
      densitySuppressed: classification.density?.meaningfulCandidate === true && classification.density?.allowed === false
    });
    if (!resolution) {
      if (typeof MatchSituationLifecycle !== "undefined"
        && match.activeSituation?.type === MatchSituationLifecycle.TYPES.groundBallDefensiveDecision) {
        abandonActiveMatchSituation(match, "noRoutineResolution");
      }
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, null, "no-routine-resolution");
      return null;
    }
    recordGroundBallSituationResolution(match, resolution);
    const event = applyRoutineDefensiveResolutionToHighSchoolMatch(match, resolution);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "routine");
    return event;
  }
  match.simulationPhase = "moment_2_ready";
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "meaningfulMomentReached", eventClassification: "playerMeaningfulDecision", decisionTension: classification.decisionTension, inning: match.inning, half: match.half,
    momentId: match.currentMomentId, domain: match.currentDomain, assignment: match.currentAssignment,
    outs: match.outs, scores: match.scores, runners: match.runners
  });
  finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "decision-created");
  return event;
}

function validateHighSchoolDecisionThrowState(match) {
  validateHighSchoolGroundLifecycleRoutes(match);
  const state = match?.groundBallInPlayState;
  if (state?.supported && !state.firstBaseContext && (state.firstBaseExecution
    || match.activeSituation?.contextSnapshot?.firstBaseContext
    || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence)) throw new Error("Invalid missing first-base participant context");
  if (state?.firstBaseContext) {
    if (!state.settlementApplied) assertHighSchoolGroundParticipant(match);
    if (state.firstBaseExecution) { validateHighSchoolFirstBaseExecution(match); return; }
    if (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.firstBaseEvidence) throw new Error("Invalid incomplete first-base execution stages");
  }
  if (state?.supported && state.defensiveAccess?.playerPosition === "三壘手" && !state.thirdBaseExecution
    && (state.secureResolution || state.decisionThrowState || state.runnerThrowTiming
      || match.activeSituation?.resolution?.executionEvidence?.thirdBaseEvidence)) throw new Error("Invalid incomplete 3B execution stages");
  if (state?.thirdBaseExecution) {
    validateHighSchoolThirdBaseExecution(match);
    return;
  }
  if (!state?.decisionThrowState || state.settlementApplied || typeof DefensiveDecisionThrowFoundation === "undefined") return;
  if (state.shortstopExecution) {
    const stored = state.shortstopExecution;
    const choice = getInfieldDecisionChoice(match.defensiveSituation, match, stored.choice.matchDecision);
    if (!choice || choice.routeId !== stored.choice.routeId) throw new Error("Stale SS legal route");
    const fresh = buildHighSchoolShortstopExecution(match, match.defensiveSituation, choice, stored.sample);
    if (!stored.resolution.actionFacts) {
      // New facts are optional for historical executed saves. Validate every
      // pre-existing SS fact against reconstruction without rewriting the source.
      const { actionFacts, executionSample, ...historicalResolution } = fresh.resolution;
      fresh.resolution = historicalResolution;
    }
    if (JSON.stringify(fresh) !== JSON.stringify(stored)
      || JSON.stringify(state.secureResolution) !== JSON.stringify(fresh.secureResolution)
      || JSON.stringify(state.decisionThrowState) !== JSON.stringify(fresh.decisionThrowState)
      || JSON.stringify(state.runnerThrowTiming) !== JSON.stringify(fresh.runnerThrowTiming)) throw new Error("Stale SS execution / timing facts");
    const evidence = match.activeSituation?.resolution?.executionEvidence;
    if (evidence && Object.entries(stored.resolution).some(([key, value]) => {
      // Pre-action-contract saves can omit these additive facts. Every present
      // copy must agree with the reconstructed execution owner, not itself.
      if (["actionFacts", "executionSample"].includes(key) && !Object.prototype.hasOwnProperty.call(evidence, key)) return false;
      return JSON.stringify(evidence[key]) !== JSON.stringify(value);
    })) throw new Error("Stale SS lifecycle execution facts");
    return;
  }
  DefensiveDecisionThrowFoundation.validateStoredStage(state.decisionThrowState, getHighSchoolControlledDecisionInput(match, state));
  const evidence = match.activeSituation?.resolution?.executionEvidence;
  // Historical stages without the new contract retain their existing admission.
  if (evidence?.actionFacts) {
    if (!Number.isFinite(evidence.executionSample) || evidence.executionSample < 0 || evidence.executionSample >= 1) throw new Error("Invalid 2B execution sample");
    const routeId = match.activeSituation.decision?.selectedRoute || state.decisionThrowState.preControlIntent;
    const choice = generateInfieldLegalChoices(match.defensiveSituation, match).find(c => c.routeId === routeId);
    if (!choice) throw new Error("Stale 2B execution route");
    const raw = choice.routeId === "coverSecondFor643" ? resolveSecondBaseCoverage643(match.defensiveSituation, choice, evidence.executionSample)
      : resolveSecondBaseInitiatedRoute(match.defensiveSituation, choice, evidence.executionSample, match);
    const fresh = attachHighSchoolInfieldActionFacts(match, match.defensiveSituation, choice, raw, evidence.executionSample);
    if (JSON.stringify(fresh.actionFacts) !== JSON.stringify(evidence.actionFacts)
      || JSON.stringify(fresh.receiverResolution) !== JSON.stringify(evidence.receiverResolution)
      || fresh.outsCreated !== evidence.outsCreated || fresh.resultCode !== evidence.resultCode) throw new Error("Stale 2B receiver / action facts");
  }
  if (state.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    DefensiveRunnerThrowSettlementFoundation.validateProjectedTiming(state.runnerThrowTiming, state.decisionThrowState, state.runnerPhysicalStates,
      match.activeSituation?.resolution?.executionEvidence);
  }
}

function resolveHighSchoolInfieldReceiver(situation, choice, sample, deliveryCompleted, match) {
  const position = choice.targetBase === "third" ? "3B" : choice.targetBase === "home" ? "C"
    : choice.targetBase === "second" || choice.targetBase === "secondThenFirst" ? "SS" : "1B";
  const legacy = position === "1B" ? situation.teammates?.firstBaseReceiver : position === "3B" ? situation.teammates?.thirdBaseReceiver
    : position === "C" ? situation.teammates?.catcher : situation.teammates?.shortstop;
  const actor = match?.rosters?.[match.defenseTeam] && typeof TeamRosterFoundation !== "undefined"
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], position) : null;
  const capabilities = actor ? getDefensiveSimulationCapability(actor, actor.position, match) : legacy?.capabilities || {};
  const fielding = Number(capabilities.fielding ?? 5), swing = (sample - .5) * 4;
  const available = Boolean((actor ? actor.id !== "player" : legacy) && legacy?.receivingAvailable !== false);
  const ready = available && fielding + swing >= 2.8;
  return Object.freeze({ receiverId: actor?.id || legacy?.id || null, receiverPosition: position, available, ready,
    secured: Boolean(deliveryCompleted && ready), status: !deliveryCompleted ? "notAttempted" : !available ? "unavailable" : ready ? "completed" : "failed",
    responsibleActor: deliveryCompleted && !ready ? "teammate" : "player",
    provenance: Object.freeze({ authority: actor ? "activeRosterReceiver+existingExecutionSample" : "declaredLegacyReceiver+existingExecutionSample",
      fielding, sample, swing, threshold: 2.8, consumedRng: false }) });
}

function getDefensiveSimulationCapability(subject = player, position = player.primaryPosition, matchContext = subject?.highSchoolMatch) {
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ fielding: subject.defense, reaction: subject.defense, range: subject.defense, arm: subject.arm, throwing: subject.arm, decision: Math.round((subject.defense + subject.contact) / 2) });
  }
  const rawSkills = subject.baseballSkills || {};
  const activeMatch = matchContext || (subject === player ? player.highSchoolMatch : null);
  const audit = getDevelopmentMatchPositionTestCapabilityAudit(subject, activeMatch);
  const skills = audit.active && !activeMatch?.completed
    ? Object.fromEntries(Object.keys(rawSkills).map(skill => [skill, audit.skills[skill]?.effective ?? rawSkills[skill]]))
    : rawSkills;
  const effectivePosition = audit.active ? audit.position : position;
  const positionTools = {
    "內野手": ["catching", "reaction", "throwing"],
    "外野手": ["catching", "range", "armStrength"],
    "捕手": ["blocking", "gameCalling", "throwing"],
    "投手": ["control", "reaction", "throwing"]
  }[position] || ["catching", "reaction", "throwing"];
  const values = positionTools.map(key => Number(skills[key]) || 0);
  const reactionSkill = Number(skills.reaction) || values[1] || 0;
  const throwingSkill = values[2] || 0;
  const armSkill = ["游擊手", "三壘手"].includes(effectivePosition) ? Number(skills.armStrength) || throwingSkill : throwingSkill;
  return Object.freeze({
    fielding: Math.round((values[0] * 2 + values[1] + (Number(subject.ballSense) || 0)) / 4),
    reaction: Math.round((reactionSkill * 2 + (Number(subject.ballSense) || 0)) / 3),
    range: Math.round(((Number(skills.range) || reactionSkill) * 2 + (Number(subject.fitness) || 0)) / 3),
    arm: Math.round((armSkill * 2 + (Number(subject.fitness) || 0)) / 3),
    throwing: Math.round((throwingSkill * 2 + (Number(subject.observe) || 0)) / 3),
    decision: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function getCurrentDefender(roster, position) {
  if (!validateActiveDefense(roster).ok) return null;
  const code = normalizePosition(position);
  return roster.lineup.find(actor => normalizePosition(actor.defensivePosition || actor.position) === code) || null;
}

function beginExecution(situation, input = {}) {
  return transition(situation, "executing", {
    executionState: {
      status: "inProgress",
      selectedRoute: input.selectedRoute || situation.decision?.selectedRoute || "",
      handoffRef: input.handoffRef || "",
      physicalConsequenceApplied: false,
      executionIdentity: input.executionIdentity || ""
    }
  }, { reason: input.reason || "physicalResolverHandoff" });
}

function normalizeSituation(saved) {
  if (!saved || typeof saved !== "object" || saved.version !== VERSION || !STATES.includes(saved.lifecycleState)) return null;
  return deepFreeze(clone(saved));
}

function resolveTiming(args){
  const {input,opportunity,selection,throwResolution:thrown,runnerState,receiverState}=args;
  Decision.validateSelection(selection,opportunity,input);
  if(!thrown||thrown.identity!==`${selection.identity}|throw-v1`||thrown.decisionIdentity!==selection.identity
    ||thrown.throwerId!==selection.defenderId||thrown.throwerPosition!==selection.position
    ||["routeId","targetRunnerId","targetBase","receiverId","receiverPosition"].some(key=>thrown[key]!==selection.route[key]))fail("stale throw / receiver / target");
  const base={version:VERSION,identity:`${thrown.identity}|timing-v1`,decisionIdentity:selection.identity,throwIdentity:thrown.identity,
    targetRunnerId:thrown.targetRunnerId,targetBase:thrown.targetBase,receiverId:thrown.receiverId,
    authority:"resolvedThrow+existingRunnerPhysicalState+receiverReadiness",variationEvidence:{consumed:false}};
  if(selection.route.action==="holdBall"){
    if(thrown.throwAttempted!==false)fail("hold includes throw");
    return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
      runnerArrival:null,ballArrival:null,receiverCompletion:null,reason:"heldBall"});
  }
  const current=(input.runnerPhysicalStates||[]).find(r=>r.runnerId===thrown.targetRunnerId);
  if(!current||!same(current,runnerState)||current.targetBase!==thrown.targetBase
    ||(current.originBase==="batter"?input.batterRunnerId!==current.runnerId:input.runners[Number(current.originBase)-1]!==current.runnerId))fail("stale runner physical state");
  const forced=Force.getForcedMovement(opportunity.context.forceChain,current.runnerId);
  if(!forced&&!Decision.isAdvancingTo(current,thrown.targetBase))fail("runner not in contest");
  if(!receiverState||receiverState.receiverId!==thrown.receiverId||!same(receiverState,input.receiverState))fail("stale receiver completion");
  const runnerArrival=deriveRunnerArrival(current);
  const noContest=!thrown.throwAttempted||thrown.throwQuality==="offline"||receiverState.ready!==true;
  const receiveDelay=Number(receiverState.receiveDelay??0),tagDelay=Number(receiverState.tagDelay??1);
  if(!Number.isFinite(receiveDelay)||receiveDelay<0||!Number.isFinite(tagDelay)||tagDelay<0)fail("invalid receiver delay");
  if(noContest)return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
    runnerArrival,ballArrival:{quality:thrown.throwQuality},receiverCompletion:{...clone(receiverState),status:"unavailableReceive"},reason:"unusableThrowOrReceiver"});
  const qualityDelay={onTarget:0,challengingReceive:1,lateWeakThrow:3}[thrown.throwQuality];
  if(qualityDelay===undefined)fail("generic timing cannot reinterpret legacy composite throw");
  const distanceDelay={short:0,medium:1,long:2}[thrown.throwDemand?.distanceClass];
  if(distanceDelay===undefined)fail("missing throw distance");
  const ballTime=4+distanceDelay+qualityDelay+(thrown.releaseQuality==="delayedRelease"?1:0);
  const completionTime=ballTime+receiveDelay;
  const margin=Math.round((runnerArrival.relativeArrival-completionTime)*1000)/1000;
  return freeze({...base,contestAvailable:true,timingClassification:classify(margin),timingMargin:margin,runnerArrival,
    ballArrival:{relativeArrival:ballTime,quality:thrown.throwQuality,releaseQuality:thrown.releaseQuality,distanceClass:thrown.throwDemand.distanceClass},
    receiverCompletion:{...clone(receiverState),status:thrown.throwQuality==="challengingReceive"?"challengedReceive":"readyReceive",
      relativeCompletion:completionTime,tagCompletion:completionTime+tagDelay},reason:"physicalArrivalComparison"});
}

function deriveRunnerArrival(current){
  if(!current||!Number.isFinite(current.speed)||!["preparedStart","normalStart","lateStart","brokenStart"].includes(current.startQuality))fail("missing runner arrival inputs");
  const start={preparedStart:-1,normalStart:0,lateStart:1,brokenStart:2}[current.startQuality];
  const progress={early:0,midway:1.5,late:3,nearArrival:4}[current.advancementProgress||"early"];
  if(progress===undefined)fail("unknown runner progress");
  return freeze({...clone(current),profile:Runner.deriveArrivalProfile(current.speed,current.startQuality),
    relativeArrival:10-Math.max(0,Math.min(20,current.speed))*0.45+start-progress});
}

function deriveSettlement(args){
  const {timing,input,opportunity,selection,resolveThirdOut}=args;
  if(!same(timing,resolveTiming(args)))fail("stale timing facts");
  const route=selection.route,hold=route.action==="holdBall",runner=timing.runnerArrival;
  const force=Force.getForcedMovement(opportunity.context.forceChain,route.targetRunnerId);
  const forced=Boolean(force&&force.targetBase===route.targetBase);
  if(!hold&&((route.forceType==="force"||route.forceType==="batterRunner")!==forced))fail("stale force semantics");
  const playType=hold?"hold":route.forceType==="batterRunner"?"batterRunner":forced?"force":"tag";
  const receiver=timing.receiverCompletion;
  const ahead=timing.contestAvailable&&timing.timingMargin>0; // Ties do not establish defense before arrival.
  const out=Boolean(ahead&&(playType==="tag"?receiver.tagAvailable===true&&receiver.tagCompletion<runner.relativeArrival:receiver.atBase===true));
  const runnersAfter=input.runners.slice(),movements=[],outIds=out?[route.targetRunnerId]:[],inTransit=[];
  const attempts=clone(args.scoringAttempts||[]);
  const known=new Set([...input.runners.filter(Boolean),input.batterRunnerId].filter(Boolean));
  if(new Set(attempts.map(a=>a.runnerId)).size!==attempts.length||attempts.some(a=>!known.has(a.runnerId)||a.runnerId===route.targetRunnerId))fail("invalid other scoring attempt");
  const contest=timing.contestAvailable&&!hold;
  if(contest){
    const origin=runnersAfter.indexOf(route.targetRunnerId);if(origin>=0)runnersAfter[origin]=null;
    if(!out&&route.targetBase==="home")attempts.push({runnerId:route.targetRunnerId,timing:"beforeThirdOut"});
    else if(!out){
      const index=["first","second","third"].indexOf(route.targetBase),occupant=runnersAfter[index];
      if(index<0)fail("invalid destination");
      if(occupant){
        const moving=Force.getForcedMovement(opportunity.context.forceChain,occupant);
        if(!moving)fail("destination occupied by a non-forced runner");
        inTransit.push(clone(moving));
      }
      runnersAfter[index]=route.targetRunnerId;
    }
    movements.push({runnerId:route.targetRunnerId,from:runner.originBase,to:out?"out":route.targetBase});
  }
  for(const attempt of attempts){const index=runnersAfter.indexOf(attempt.runnerId);if(index>=0)runnersAfter[index]=null;}
  const dp=route.action==="initiateDoublePlay";
  const continuation={status:hold?"heldBallAwaitRunnerContinuation":!contest?"liveBallRecoveryRequired":dp&&out?"secondLegPending":dp?"reassessAfterSafeFirstLeg":"liveBallContinuation",
    targetBase:dp&&out?"first":null,inTransitRunners:inTransit,
    pendingRunners:(input.runnerPhysicalStates||[]).filter(r=>r.runnerId!==route.targetRunnerId||!contest).map(clone)};
  return completeSettlement({identity:`${timing.identity}|settlement-v1`,timing,routeId:route.routeId,targetRunnerId:route.targetRunnerId,targetBase:route.targetBase,
    playType,runnerResult:hold?"held":!contest?"unresolved":out?"out":"safe",before:{outs:input.outs,runners:input.runners,scores:input.scores||null},
    runnersAfter,outIds,scoringAttempts:attempts,runnerMovement:movements,forceBefore:opportunity.context.forceChain,continuation,resolveThirdOut});
}

function settleForceAdvancement({ forceChain, route = "", resultCode = "", movementIntents, retirements: suppliedRetirements } = {}) {
  if (!forceChain) return null;
  const batterId = forceChain.batterRunner.runnerId;
  const runnerAtFirst = forceChain.sourceBaseState[0];
  const intents = movementIntents || buildMovementIntents(forceChain);
  const actors = [...forceChain.allRequiredMovements, ...forceChain.unforcedRunners];
  if (intents.length !== actors.length || new Set(intents.map(actor => actor.runnerId)).size !== actors.length
    || intents.some(intent => !actors.some(actor => actor.runnerId === intent.runnerId && actor.originBase === intent.originBase)
      || !BASE_NAMES.includes(intent.targetBase))) throw new Error("Incomplete runner movement identities");
  const candidates = [];
  const retire = (runnerId, targetBase, outType) => { if (runnerId) candidates.push({ runnerId, targetBase, outType, sequence: candidates.length + 1 }); };
  if (suppliedRetirements) candidates.push(...clone(suppliedRetirements));
  else if (route === "doublePlay") {
    if (["oneOut", "twoOuts"].includes(resultCode)) retire(runnerAtFirst, "second", "force");
    if (resultCode === "twoOuts") retire(batterId, "first", "batterRunnerBeforeFirst");
  } else if (resultCode === "oneOut") {
    if (route === "secureFirst") retire(batterId, "first", "batterRunnerBeforeFirst");
    if (route === "forceSecond") retire(runnerAtFirst, "second", "force");
    if (route === "forceThird") retire(forceChain.sourceBaseState[1], "third", "force");
    if (route === "forceHome") retire(forceChain.sourceBaseState[2], "home", "force");
    if (route === "tagHome") retire(forceChain.sourceBaseState[2], "home", "nonForceTag");
  }
  const outRunnerIds = new Set();
  let liveForce = forceChain;
  const retirements = [], continuationClassifications = [];
  for (const candidate of candidates) {
    if (!intents.some(actor => actor.runnerId === candidate.runnerId) || outRunnerIds.has(candidate.runnerId)) throw new Error("Invalid retirement identity");
    if (candidate.sequence !== retirements.length + continuationClassifications.length + 1) throw new Error("Invalid retirement sequence");
    const legality = classifyContinuationTarget(liveForce, candidate.runnerId, candidate.targetBase);
    if (candidate.outType === "force" && !legality.forceAvailable) {
      continuationClassifications.push({ ...legality, sequence: candidate.sequence });
      continue;
    }
    if (!["force", "batterRunnerBeforeFirst", "nonForceTag"].includes(candidate.outType)
      || (candidate.outType === "batterRunnerBeforeFirst" && (candidate.runnerId !== batterId || candidate.targetBase !== "first"))) throw new Error("Invalid retirement type");
    outRunnerIds.add(candidate.runnerId);
    const forceStateAtRetirement = { forceTargets: clone(liveForce.forceTargets) };
    liveForce = deriveForceChainAfterRetirements(liveForce, [candidate.runnerId]);
    retirements.push({ ...candidate, forceStateAtRetirement, isBatterRunner: candidate.runnerId === batterId,
      beforeFirst: candidate.outType === "batterRunnerBeforeFirst", forceTargetsAfter: clone(liveForce.forceTargets) });
  }
  const outcomes = [];
  const addOutcome = (actor, targetBase) => {
    const resolvedTarget = outRunnerIds.has(actor.runnerId) ? "out" : targetBase;
    const numericTarget = BASE_NAMES.indexOf(resolvedTarget);
    outcomes.push(deepFreeze({
      runnerId: actor.runnerId,
      from: actor.originBase,
      to: numericTarget >= 0 && numericTarget < 3 ? numericTarget + 1 : resolvedTarget,
      targetBase: resolvedTarget,
      isForced: actor.forced === true,
      movementRequired: actor.movementRequired, committed: actor.committed,
      retired: resolvedTarget === "out", safe: resolvedTarget !== "out", scored: resolvedTarget === "home",
      forceReason: getForcedMovement(forceChain, actor.runnerId)?.forceReason || ""
    }));
  };
  // Initial committed movement survives removal of the force; retirement overrides it.
  intents.forEach(actor => addOutcome(actor, actor.targetBase));
  const runnersAfter = [null, null, null];
  const scoringRunnerIds = [];
  outcomes.forEach(outcome => {
    if (outcome.targetBase === "out") return;
    if (outcome.targetBase === "home") {
      scoringRunnerIds.push(outcome.runnerId);
      return;
    }
    const baseIndex = BASE_NAMES.indexOf(outcome.targetBase);
    if (baseIndex < 0 || baseIndex > 2 || runnersAfter[baseIndex]) throw new Error("Unresolved runner destination collision");
    runnersAfter[baseIndex] = outcome.runnerId;
  });
  return deepFreeze({
    version: "force-advancement-settlement-v1",
    authority: "actorOutcomesThenBaseOccupancyRebuild",
    runnersAfter,
    runnerChanges: outcomes,
    scoringRunnerIds,
    runsAllowed: scoringRunnerIds.length,
    outRunnerIds: [...outRunnerIds], outsCreated: outRunnerIds.size,
    initialForceChain: forceChain, movementIntents: clone(intents), retirements,
    forceChainAfterRetirements: liveForce, continuationClassifications,
    survivors: outcomes.filter(actor => !actor.retired)
